package net.officefloor.hq.app.client;

import jakarta.validation.Valid;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/clients")
public class ClientController {

    private final ClientService service;

    public ClientController(ClientService service) {
        this.service = service;
    }

    @GetMapping
    public List<ClientResponse> list(@RequestParam(defaultValue = "false") boolean includeArchived) {
        return service.list(includeArchived);
    }

    @GetMapping("/{id}")
    public ClientResponse get(@PathVariable Long id) {
        return service.get(id);
    }

    @GetMapping("/{id}/summary")
    public ClientSummaryResponse summary(@PathVariable Long id) {
        return service.summary(id);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ClientResponse create(@Valid @RequestBody ClientRequest request) {
        return service.create(request);
    }

    @PutMapping("/{id}")
    public ClientResponse update(@PathVariable Long id, @Valid @RequestBody ClientRequest request) {
        return service.update(id, request);
    }

    @PutMapping("/{id}/currency")
    public ClientResponse changeCurrency(@PathVariable Long id, @Valid @RequestBody ClientCurrencyRequest request) {
        return service.changeCurrency(id, request.currency());
    }

    @PostMapping("/{id}/archive")
    public ClientResponse archive(@PathVariable Long id) {
        return service.archive(id);
    }

    @PostMapping("/{id}/restore")
    public ClientResponse restore(@PathVariable Long id) {
        return service.restore(id);
    }
}
package net.officefloor.hq.app.client;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.contact.ContactRepository;
import net.officefloor.hq.app.creditnote.CreditNoteRepository;
import net.officefloor.hq.app.invoice.InvoiceRepository;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import net.officefloor.hq.app.payment.PaymentRepository;
import net.officefloor.hq.app.project.ProjectRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.data.domain.Sort;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ClientService {

    private final ClientRepository clients;
    private final ProjectRepository projects;
    private final ContactRepository contacts;
    private final InvoiceRepository invoices;
    private final PaymentRepository payments;
    private final CreditNoteRepository creditNotes;
    private final Audit audit;

    public ClientService(ClientRepository clients, ProjectRepository projects, ContactRepository contacts,
            InvoiceRepository invoices, PaymentRepository payments, CreditNoteRepository creditNotes, Audit audit) {
        this.clients = clients;
        this.projects = projects;
        this.contacts = contacts;
        this.invoices = invoices;
        this.payments = payments;
        this.creditNotes = creditNotes;
        this.audit = audit;
    }

    /** The clients, leaving out archived ones unless they are asked for. */
    @Transactional(readOnly = true)
    public List<ClientResponse> list(boolean includeArchived) {
        List<Client> found = includeArchived ? clients.findAll(Sort.by("id")) : clients.findByArchivedFalseOrderById();
        return respond(found);
    }

    @Transactional(readOnly = true)
    public ClientResponse get(Long id) {
        return respond(find(id));
    }

    /** Invoices that have been issued to the client: everything but drafts and cancelled invoices. */
    private static final List<InvoiceStatus> BILLED = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL,
            InvoiceStatus.PAID, InvoiceStatus.WRITTEN_OFF);

    /** At-a-glance counts of what one client has, and the total ever billed to them. */
    @Transactional(readOnly = true)
    public ClientSummaryResponse summary(Long id) {
        if (!clients.existsById(id)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
        }
        BigDecimal billed = invoices.sumAmountByClientIdAndStatusIn(id, BILLED).setScale(2, RoundingMode.HALF_UP);
        return new ClientSummaryResponse(projects.countByClientId(id), contacts.countByClientId(id), billed);
    }

    /** Adds a client; its email, once trimmed, must not already belong to another client. */
    @Transactional
    public ClientResponse create(ClientRequest request) {
        String email = request.email().trim();
        if (clients.existsByEmailIgnoreCase(email)) {
            throw emailTaken();
        }
        try {
            Client client = new Client(request.name().trim(), email, request.trimmedPhone(), request.trimmedTaxNumber(), request.trimmedBillingAddress());
            client.setTaxInclusive(Boolean.TRUE.equals(request.taxInclusive()));
            client.setTaxExempt(Boolean.TRUE.equals(request.taxExempt()));
            client.setKeyAccount(Boolean.TRUE.equals(request.keyAccount()));
            if (request.defaultDiscountPct() != null) {
                client.setDefaultDiscountPct(request.defaultDiscountPct());
            }
            return respond(clients.saveAndFlush(client));
        } catch (DataIntegrityViolationException e) {
            // Lost a race with a concurrent add of the same email; the unique constraint caught it.
            if (String.valueOf(e.getMessage()).toUpperCase().contains("CLIENT_EMAIL_UQ")) {
                throw emailTaken();
            }
            throw e;
        }
    }

    /**
     * Corrects a client's name, email, phone number, tax number and billing address; the email, once trimmed, must not belong to another client.
     * When whether their prices include tax, or whether they are tax exempt, changes, their draft invoices are reworked to match; sent ones keep the
     * figures they were issued with. The change is recorded in the audit log.
     */
    @Transactional
    public ClientResponse update(Long id, ClientRequest request) {
        Client client = find(id);
        String email = request.email().trim();
        if (clients.existsByEmailIgnoreCaseAndIdNot(email, id)) {
            throw emailTaken();
        }
        client.rename(request.name().trim(), email, request.trimmedPhone(), request.trimmedTaxNumber(), request.trimmedBillingAddress());
        if (request.taxInclusive() != null && request.taxInclusive() != client.isTaxInclusive()) {
            client.setTaxInclusive(request.taxInclusive());
            invoices.findByClientIdAndStatus(id, InvoiceStatus.DRAFT)
                    .forEach(i -> i.applyTaxInclusive(request.taxInclusive()));
        }
        if (request.taxExempt() != null && request.taxExempt() != client.isTaxExempt()) {
            client.setTaxExempt(request.taxExempt());
            invoices.findByClientIdAndStatus(id, InvoiceStatus.DRAFT)
                    .forEach(i -> i.applyTaxExempt(request.taxExempt()));
        }
        if (request.keyAccount() != null) {
            client.setKeyAccount(request.keyAccount());
        }
        // Only invoices raised from now on start with the standard discount; existing ones keep theirs.
        if (request.defaultDiscountPct() != null) {
            client.setDefaultDiscountPct(request.defaultDiscountPct());
        }
        try {
            clients.flush();
        } catch (DataIntegrityViolationException e) {
            // Lost a race with a concurrent change to the same email; the unique constraint caught it.
            if (String.valueOf(e.getMessage()).toUpperCase().contains("CLIENT_EMAIL_UQ")) {
                throw emailTaken();
            }
            throw e;
        }
        audit.record("CLIENT_UPDATED id=" + id);
        return respond(client);
    }

    /** Changes the currency a client is billed in, recording the change in the audit log. */
    @Transactional
    public ClientResponse changeCurrency(Long id, Currency currency) {
        Client client = find(id);
        if (client.getCurrency() != currency) {
            client.setCurrency(currency);
            clients.flush();
            audit.record("CLIENT_CURRENCY_CHANGED id=" + id + " currency=" + currency);
        }
        return respond(client);
    }

    private static ResponseStatusException emailTaken() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "A client with this email already exists");
    }

    /**
     * Archives a client: it drops off the client list and search but is kept, with its projects and
     * contacts, and the archiving is recorded in the audit log.
     */
    @Transactional
    public ClientResponse archive(Long id) {
        Client client = find(id);
        if (!client.isArchived()) {
            client.setArchived(true);
            clients.flush();
            audit.record("CLIENT_ARCHIVED id=" + id);
        }
        return respond(client);
    }

    /** Brings an archived client back onto the client list, recording it in the audit log. */
    @Transactional
    public ClientResponse restore(Long id) {
        Client client = find(id);
        if (client.isArchived()) {
            client.setArchived(false);
            clients.flush();
            audit.record("CLIENT_RESTORED id=" + id);
        }
        return respond(client);
    }

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    /** The given clients, each with what they still owe. */
    @Transactional(readOnly = true)
    public List<ClientResponse> respond(List<Client> found) {
        Map<Long, BigDecimal> owed = outstandingByClient();
        return found.stream().map(c -> ClientResponse.from(c, owed.getOrDefault(c.getId(), ZERO))).toList();
    }

    /**
     * The clients who owe the most, largest debt first (ties by id), at most {@code limit} of them.
     * Clients owing nothing are left out.
     */
    @Transactional(readOnly = true)
    public List<ClientResponse> topByOutstanding(int limit) {
        Map<Long, BigDecimal> owed = outstandingByClient();
        owed.values().removeIf(amount -> amount.signum() <= 0);
        List<Long> top = owed.entrySet().stream()
                .sorted(Map.Entry.<Long, BigDecimal>comparingByValue().reversed()
                        .thenComparing(Map.Entry.comparingByKey()))
                .limit(limit)
                .map(Map.Entry::getKey)
                .toList();
        Map<Long, Client> found = new HashMap<>();
        clients.findAllById(top).forEach(c -> found.put(c.getId(), c));
        return top.stream().map(id -> ClientResponse.from(found.get(id), owed.get(id))).toList();
    }

    /**
     * What is still owed in each currency, each client's debt counted in their own currency; amounts
     * in different currencies are never added together. Currencies nothing is owed in are left out.
     */
    @Transactional(readOnly = true)
    public Map<Currency, BigDecimal> outstandingByCurrency() {
        Map<Long, BigDecimal> owed = outstandingByClient();
        Map<Currency, BigDecimal> totals = new EnumMap<>(Currency.class);
        clients.findAllById(owed.keySet())
                .forEach(c -> totals.merge(c.getCurrency(), owed.get(c.getId()), BigDecimal::add));
        totals.values().removeIf(amount -> amount.signum() == 0);
        return totals;
    }

    private ClientResponse respond(Client client) {
        return ClientResponse.from(client, outstandingByClient().getOrDefault(client.getId(), ZERO));
    }

    /**
     * What each client still owes: what is left to pay on their sent invoices that are not yet fully
     * paid, after the payments and credit notes against them. Clients owing nothing are left out.
     */
    private Map<Long, BigDecimal> outstandingByClient() {
        List<InvoiceStatus> owing = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL);
        Map<Long, BigDecimal> owed = new HashMap<>();
        invoices.sumAmountByStatusInPerClient(owing).forEach(t -> owed.merge(t.getClientId(), t.getTotal(),
                BigDecimal::add));
        payments.sumAmountByInvoiceStatusInPerClient(owing).forEach(t -> owed.merge(t.getClientId(),
                t.getTotal().negate(), BigDecimal::add));
        creditNotes.sumAmountByInvoiceStatusInPerClient(owing).forEach(t -> owed.merge(t.getClientId(),
                t.getTotal().negate(), BigDecimal::add));
        owed.replaceAll((id, amount) -> amount.setScale(2, RoundingMode.HALF_UP));
        return owed;
    }

    private Client find(Long id) {
        return clients.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
    }
}
package net.officefloor.hq.app.client;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface ClientRepository extends JpaRepository<Client, Long> {

    /** All clients not archived, in id order. */
    List<Client> findByArchivedFalseOrderById();

    /** Whether any client, archived or not, already has the email, ignoring case. */
    boolean existsByEmailIgnoreCase(String email);

    /** Whether any client other than the given one already has the email, ignoring case. */
    boolean existsByEmailIgnoreCaseAndIdNot(String email, Long id);

    /** Clients not archived whose name contains the text, ignoring case, in id order. */
    @Query("SELECT c FROM Client c WHERE c.archived = false AND LOWER(c.name) LIKE LOWER(CONCAT('%', :text, '%'))"
            + " ESCAPE '\\' ORDER BY c.id")
    List<Client> searchActiveByName(String text);
}
package net.officefloor.hq.app.client;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.contact.Contact;

/** A client of the office. */
@Entity
@Table(name = "client")
public class Client {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    private String email;

    /** A number to reach the client on; none when not known. */
    private String phone;

    /** The client's tax registration number; none when they are not tax registered. */
    private String taxNumber;

    /** Where the client's bills are sent; none when not known. */
    private String billingAddress;

    private boolean archived;

    /** Whether the client's prices already include tax, so tax is worked back out of them rather than added on. */
    private boolean taxInclusive;

    /** Whether the client is tax exempt, so none of their invoices carry any tax whatever the lines say. */
    private boolean taxExempt;

    /** Whether the client is one of the office's key accounts, marked out wherever they are listed. */
    private boolean keyAccount;

    /** The client's standard discount, a percentage each new invoice for them starts with; zero when none. */
    @Column(name = "default_discount_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal defaultDiscountPct = BigDecimal.ZERO.setScale(2);

    /** The currency the client is billed in; all of their money is in it. */
    @Enumerated(EnumType.STRING)
    private Currency currency = Currency.USD;

    /** The client's main contact, one of its own contacts; none until one is chosen. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "primary_contact_id")
    private Contact primaryContact;

    protected Client() {
    }

    public Client(String name, String email, String phone, String taxNumber, String billingAddress) {
        this.name = name;
        this.email = email;
        this.phone = phone;
        this.taxNumber = taxNumber;
        this.billingAddress = billingAddress;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public String getPhone() {
        return phone;
    }

    public String getTaxNumber() {
        return taxNumber;
    }

    public String getBillingAddress() {
        return billingAddress;
    }

    /** Corrects the client's name, email, phone number, tax number and billing address. */
    public void rename(String name, String email, String phone, String taxNumber, String billingAddress) {
        this.name = name;
        this.email = email;
        this.phone = phone;
        this.taxNumber = taxNumber;
        this.billingAddress = billingAddress;
    }

    public boolean isTaxInclusive() {
        return taxInclusive;
    }

    public void setTaxInclusive(boolean taxInclusive) {
        this.taxInclusive = taxInclusive;
    }

    public boolean isTaxExempt() {
        return taxExempt;
    }

    public void setTaxExempt(boolean taxExempt) {
        this.taxExempt = taxExempt;
    }

    public boolean isKeyAccount() {
        return keyAccount;
    }

    public void setKeyAccount(boolean keyAccount) {
        this.keyAccount = keyAccount;
    }

    public BigDecimal getDefaultDiscountPct() {
        return defaultDiscountPct;
    }

    public void setDefaultDiscountPct(BigDecimal defaultDiscountPct) {
        this.defaultDiscountPct = defaultDiscountPct.setScale(2, RoundingMode.HALF_UP);
    }

    public boolean isArchived() {
        return archived;
    }

    public void setArchived(boolean archived) {
        this.archived = archived;
    }

    public Currency getCurrency() {
        return currency;
    }

    public void setCurrency(Currency currency) {
        this.currency = currency;
    }

    public Contact getPrimaryContact() {
        return primaryContact;
    }

    public void setPrimaryContact(Contact primaryContact) {
        this.primaryContact = primaryContact;
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
CREATE TABLE client (
    id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name  VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL
);
CREATE TABLE contact (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id BIGINT       NOT NULL,
    name      VARCHAR(255) NOT NULL,
    email     VARCHAR(255) NOT NULL,
    role      VARCHAR(255) NOT NULL,
    CONSTRAINT contact_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    -- Backstop for the API validation, matching the client email rule.
    CONSTRAINT contact_email_format CHECK (email LIKE '_%@_%._%' AND email NOT LIKE '% %')
);

CREATE INDEX contact_client_idx ON contact (client_id);
-- Each client can have one main contact, chosen from its own contacts. The composite key makes the
-- database refuse a main contact that belongs to another client.
ALTER TABLE contact ADD CONSTRAINT contact_id_client_uq UNIQUE (id, client_id);
ALTER TABLE client ADD COLUMN primary_contact_id BIGINT;
ALTER TABLE client ADD CONSTRAINT client_primary_contact_fk
    FOREIGN KEY (primary_contact_id, id) REFERENCES contact (id, client_id);
-- A lump sum a client pays in one go, split across several of their invoices. Each share is still
-- recorded as an ordinary payment against its invoice, linked back to the lump it came from.
CREATE TABLE client_payment (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id BIGINT         NOT NULL,
    amount    DECIMAL(12, 2) NOT NULL,
    paid_date DATE           NOT NULL,
    CONSTRAINT client_payment_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    CONSTRAINT client_payment_amount_positive CHECK (amount > 0)
);

CREATE INDEX client_payment_client_idx ON client_payment (client_id, paid_date);

ALTER TABLE payment ADD COLUMN client_payment_id BIGINT;
ALTER TABLE payment ADD CONSTRAINT payment_client_payment_fk
    FOREIGN KEY (client_payment_id) REFERENCES client_payment (id);
CREATE TABLE project (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name      VARCHAR(255) NOT NULL,
    client_id BIGINT       NOT NULL,
    CONSTRAINT project_client_fk FOREIGN KEY (client_id) REFERENCES client (id)
);

CREATE INDEX project_client_idx ON project (client_id);
-- Money a client pays up front, before any invoice. It is held against the client.
CREATE TABLE deposit (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id BIGINT         NOT NULL,
    amount    DECIMAL(12, 2) NOT NULL,
    paid_date DATE           NOT NULL,
    CONSTRAINT deposit_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    CONSTRAINT deposit_amount_positive CHECK (amount > 0)
);

CREATE INDEX deposit_client_idx ON deposit (client_id, paid_date);
-- Part of a client's held deposits put toward their invoices in one go, split the same way as a lump
-- payment. Each share is recorded as an ordinary payment against its invoice, linked back to the
-- application it came from; what is still held is the deposits less everything applied.
CREATE TABLE deposit_application (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id  BIGINT         NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    applied_on DATE           NOT NULL,
    CONSTRAINT deposit_application_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    CONSTRAINT deposit_application_amount_positive CHECK (amount > 0)
);

CREATE INDEX deposit_application_client_idx ON deposit_application (client_id, applied_on);

ALTER TABLE payment ADD COLUMN deposit_application_id BIGINT;
ALTER TABLE payment ADD CONSTRAINT payment_deposit_application_fk
    FOREIGN KEY (deposit_application_id) REFERENCES deposit_application (id);
-- Unused credit (held deposits and unused credit notes) paid back to a client. A refund draws on
-- the held deposits first and then on unused credit notes; the split is kept so each part of the
-- client's credit drops by exactly what was refunded from it.
CREATE TABLE refund (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id         BIGINT         NOT NULL,
    amount            DECIMAL(12, 2) NOT NULL,
    from_deposits     DECIMAL(12, 2) NOT NULL,
    from_credit_notes DECIMAL(12, 2) NOT NULL,
    refunded_on       DATE           NOT NULL,
    note              VARCHAR(500),
    CONSTRAINT refund_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    CONSTRAINT refund_amount_positive CHECK (amount > 0),
    CONSTRAINT refund_split_matches CHECK (from_deposits >= 0 AND from_credit_notes >= 0
        AND from_deposits + from_credit_notes = amount)
);

CREATE INDEX refund_client_idx ON refund (client_id, refunded_on);
